#include <WiFi.h>
#include <WebServer.h>
#include <Adafruit_NeoPixel.h>

const int NUM_PIXELS = 8;
Adafruit_NeoPixel strip(NUM_PIXELS, NEOPIXEL_PIN, NEO_GRB + NEO_KHZ800);

WebServer server(80);
int lastR = 0, lastG = 0, lastB = 0;

const char PAGE[] = R"(
<!DOCTYPE html>
<html>
<head><meta name="viewport" content="width=device-width"></head>
<body style="font-family: sans-serif; text-align: center">
  <h1>NeoPixel Remote</h1>
  <form action="/colour">
    <p>Red <input type="range" name="r" min="0" max="255"></p>
    <p>Green <input type="range" name="g" min="0" max="255"></p>
    <p>Blue <input type="range" name="b" min="0" max="255"></p>
    <p><button style="font-size: 2em">Light up!</button></p>
  </form>
  <p><a href="/party"><button style="font-size: 2em">Party!</button></a></p>
</body>
</html>
)";

void fillStrip(int r, int g, int b) {
  for (int i = 0; i < NUM_PIXELS; i++) {
    strip.setPixelColor(i, strip.Color(r, g, b));
  }
  strip.show();
}

void homePage() {
  server.send(200, "text/html", PAGE);
}

void setColour() {
  lastR = server.arg("r").toInt();  // the number after r= in the address
  lastG = server.arg("g").toInt();
  lastB = server.arg("b").toInt();
  fillStrip(lastR, lastG, lastB);
  Serial.print("Colour: ");
  Serial.print(lastR);
  Serial.print(", ");
  Serial.print(lastG);
  Serial.print(", ");
  Serial.println(lastB);
  server.send(200, "text/html", PAGE);
}

void party() {
  server.send(200, "text/html", PAGE);
  for (int i = 0; i < 10; i++) {
    fillStrip(random(256), random(256), random(256));
    delay(200);
  }
  fillStrip(lastR, lastG, lastB);
  Serial.println("Party!");
}

void setup() {
  Serial.begin(115200);
  strip.begin();
  strip.setBrightness(40);
  strip.show();
  WiFi.softAP("ArduinoPath-Lights", "circuit123");
  server.on("/", homePage);
  server.on("/colour", setColour);
  server.on("/party", party);
  server.begin();
  Serial.print("Open http://");
  Serial.println(WiFi.softAPIP());
}

void loop() {
  server.handleClient();
}
